import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> in html.

    The html string is already fetched; this function must not use the network.
    Return an empty string when there is no title element.
    """
    match = re.search(r"<title\b[^>]*>(.*?)</title\s*>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return str(match.group(1))


def test_title_of_returns_text_between_tags() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_title_of_returns_empty_string_when_missing() -> None:
    assert title_of("<html><head></head><body>No title here</body></html>") == ""


def test_title_of_returns_empty_string_for_empty_input() -> None:
    assert title_of("") == ""
